CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE merchants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id varchar(64) NOT NULL UNIQUE, name varchar(128) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), key_hash varchar(256) NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_endpoints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), url varchar(2048) NOT NULL, secret_hash varchar(256) NOT NULL, signing_material varchar(512) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id varchar(64) NOT NULL UNIQUE, merchant_id uuid NOT NULL REFERENCES merchants(id), merchant_order_reference varchar(128) NOT NULL, idempotency_key varchar(128) NOT NULL, status varchar(32) NOT NULL CHECK (status IN ('created','awaiting_payment','transaction_submitted','confirming','paid','expired','underpaid','overpaid_review','failed','cancelled')), fiat_amount varchar(40) NOT NULL, fiat_currency varchar(3) NOT NULL, allowed_rails jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(merchant_id, merchant_order_reference), UNIQUE(merchant_id, idempotency_key));
CREATE TABLE quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), rail_id varchar(32) NOT NULL, family varchar(24) NOT NULL, network_name varchar(64) NOT NULL, chain_id varchar(32) NOT NULL, asset varchar(16) NOT NULL, token_id varchar(128), decimals integer NOT NULL, amount_base_units varchar(80) NOT NULL CHECK (amount_base_units ~ '^[1-9][0-9]*$'), rate varchar(80) NOT NULL, rate_source varchar(128) NOT NULL, destination varchar(128) NOT NULL, required_confirmations integer NOT NULL, underpay_bps integer NOT NULL, overpay_bps integer NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), selected_quote_id uuid NOT NULL REFERENCES quotes(id), chain_namespace varchar(32) NOT NULL, hash varchar(128) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT payment_tx_chain_namespace_hash_unique UNIQUE(chain_namespace, hash));
CREATE TABLE payment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), type varchar(64) NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE verification_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_transaction_id uuid NOT NULL REFERENCES payment_transactions(id), result varchar(32) NOT NULL, evidence jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE verification_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_transaction_id uuid NOT NULL UNIQUE REFERENCES payment_transactions(id), attempts varchar(8) NOT NULL DEFAULT '0', due_at timestamptz NOT NULL, lease_until timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), type varchar(64) NOT NULL, body jsonb NOT NULL, canonical_body varchar(8192) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), webhook_event_id uuid NOT NULL REFERENCES webhook_events(id), endpoint_id uuid NOT NULL REFERENCES webhook_endpoints(id), due_at timestamptz NOT NULL, lease_until timestamptz, attempts varchar(8) NOT NULL DEFAULT '0', response_status varchar(8), response_excerpt varchar(512), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX verification_jobs_claim_idx ON verification_jobs(due_at, lease_until);
CREATE UNIQUE INDEX webhook_delivery_event_endpoint_unique ON webhook_deliveries(webhook_event_id, endpoint_id);
CREATE INDEX webhook_deliveries_claim_idx ON webhook_deliveries(due_at, lease_until);